async function openResolvedJson(path: string, anchorElement: HTMLElement, viewMode: WorkspaceViewMode) {
    try {
        const document = await jsonDataService.open(path);
        if (viewMode === 'cards') {
            const popupDocument = openFilesService.openJsonPopupDocument(document);
            cardPopupService.openJsonData(popupDocument, anchorElement);
        }
        if (viewMode === 'text') openFilesService.openJsonDocument(document);
    } catch (error) {
        dialogService.error(error, { fallbackMessage: `JSON file could not be opened: ${path}` });
    }
}

/** Starts JSON navigation when link and current workspace view are eligible for application routing. */
export function routeJsonProjectLink(sourcePath: string, href: string, anchorElement: HTMLElement) {
    const { snapshot } = dataService.getState();
    const path = resolveJsonProjectLink(sourcePath, href, snapshot?.repositoryFiles ?? []);
    if (!path) return false;

    const { viewMode } = workspaceViewService.getSnapshot();
    if (viewMode !== 'cards' && viewMode !== 'text') return false;

    void openResolvedJson(path, anchorElement, viewMode);

    return true;
}

import { normalizePath } from '../../../../shared/path_utils.mjs';

function resolveSegments(sourcePath: string, linkPath: string) {
    const sourceSegments = normalizePath(sourcePath).split('/');
    sourceSegments.pop();
    const segments = linkPath.startsWith('/') ? [] : sourceSegments;
    const linkSegments = normalizePath(linkPath).replace(/^\/+/, '').split('/');

    for (const segment of linkSegments) {
        if (!segment || segment === '.') continue;
        if (segment === '..') {
            if (segments.length === 0) return null;
            segments.pop();
            continue;
        }
        segments.push(segment);
    }

    return segments.join('/');
}

/** Resolves one Markdown link to an existing repository JSON path, or leaves normal link handling intact. */
export function resolveJsonProjectLink(
    sourcePath: string,
    href: string,
    repositoryPaths: readonly string[],
) {
    const trimmedHref = href.trim();
    if (!trimmedHref || trimmedHref.startsWith('#') || trimmedHref.startsWith('//')) return null;
    if (/^[a-z][a-z\d+.-]*:/iu.test(trimmedHref)) return null;
    if (trimmedHref.includes('?') || trimmedHref.includes('#')) return null;

    let decodedPath: string;
    try {
        decodedPath = decodeURIComponent(trimmedHref);
    } catch {
        return null;
    }
    if (!decodedPath.toLowerCase().endsWith('.json')) return null;

    const resolvedPath = resolveSegments(sourcePath, decodedPath);
    if (!resolvedPath) return null;
    const normalizedResolvedPath = normalizePath(resolvedPath);

    return repositoryPaths.find((path) => normalizePath(path) === normalizedResolvedPath) ?? normalizedResolvedPath;
}

