describe('renderer navigation guards', () => {
    function createWebContents() {
        const listeners = {};
        const webContents = {
            on: vi.fn((event, listener) => { listeners[event] = listener; }),
            setWindowOpenHandler: vi.fn((handler) => { webContents.windowOpenHandler = handler; }),
